import {sampleRows,defaultMapping,initialState,mapRows,stats,isComplete,pickPlayer,validateAmount,recordOutcome,changeUnit,deleteTeam,money,workbookRows,defaultBudget,teamStats,migrateState,validateBudget,validateSale,startUnsoldRound,reviseSale} from './core.mjs';
import {createWorkbook,download,readWorkbook} from './workbook.mjs';
const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root'),storageKey='auction-house-premium-v1';
let state=initialState();try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved)state=migrateState(saved);}catch{}
const sidebarPreferenceKey='auction-house-premium-collapsed';
const ui={sidebarCollapsed:false,spinning:false,rotation:0,teamId:null,amount:'',error:'',last:null,filter:'All',fileName:state.fileName||'arena_registrations.xlsx',importing:false,modal:null,logoDraft:'',spinToken:0};
try{ui.sidebarCollapsed=localStorage.getItem(sidebarPreferenceKey)==='true';}catch{}
let autoTimer,spinTimer,toastTimer,lastFocus;
const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const icons={collapse:'<path d="m14 6-6 6 6 6"/>',expand:'<path d="m10 6 6 6-6 6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.3"/><rect x="14" y="3" width="7" height="7" rx="1.3"/><rect x="3" y="14" width="7" height="7" rx="1.3"/><rect x="14" y="14" width="7" height="7" rx="1.3"/>',upload:'<path d="M12 16V3m-4 4 4-4 4 4M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M15 3.1a4 4 0 0 1 0 7.8"/><circle cx="9" cy="7" r="4"/>',wheel:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="2.5"/><path d="M12 3v6.5m0 5V21M3 12h6.5m5 0H21m-15.4-6.4L10 10m4 4 4.4 4.4m0-12.8L14 10m-4 4-4.4 4.4"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V6m5 10v-8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Zm0 0v6h6M8 13h8m-8 4h5"/>',check:'<path d="m5 12 4 4L19 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',download:'<path d="M12 3v13m-4-4 4 4 4-4M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="m15 4 5 5M4 20l1-6L16 3a2 2 0 0 1 3 0l2 2a2 2 0 0 1 0 3L10 19Z"/>',trash:'<path d="M3 6h18m-16 0 1 15h12l1-15M9 6V3h6v3m-5 4v7m4-7v7"/>',reset:'<path d="M3 10a9 9 0 1 1 1.5 8M3 4v6h6"/>',trophy:'<path d="M7 3h10v6a5 5 0 0 1-10 0Zm0 2H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 2v6m-5 1h10"/>',flag:'<path d="M5 21V3m0 0h14l-3 4 3 4H5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',eyeoff:'<path d="m3 3 18 18M10.6 10.6a2 2 0 0 0 2.8 2.8M9.5 4.3A10 10 0 0 1 12 4c6 0 10 8 10 8a16 16 0 0 1-4 4.7M6.2 6.2C3.4 8.5 2 12 2 12s4 8 10 8a11 11 0 0 0 5-1.5"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',rupee:'<path d="M5 4h14M5 9h14M7 4a5 5 0 0 1 0 10H5l11 7"/>'};
function icon(name,extra=''){return `<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]??icons.grid}</svg>`;}
function brandMark(){return '<svg class="brand-mark" viewBox="0 0 40 40" aria-hidden="true"><rect width="40" height="40" rx="12" fill="currentColor"/><path d="M11 9h11c8 0 11 9 5 13 6 5 1 10-6 10H11Zm7 6v5h4c4 0 4-5 0-5Zm0 11v3h4c4 0 4-3 0-3Z" fill="white"/></svg>';}
function portrait(p,large=false){const i=Math.abs([...p.id].reduce((n,c)=>n+c.charCodeAt(0),0))%6;const bg=['#e4eadc','#e4e9eb','#efe8dc','#e7e1eb','#e7e9d9','#e3ece3'][i],shirt=['#557d4d','#567d93','#997943','#806394','#88964f','#456d60'][i],skin=['#cc966e','#b87e58','#cf9a72','#b4805a','#c08a68','#d5a078'][i];const url=/^(https?:\/\/|data:image\/(png|jpeg|webp);base64,)/i.test(p.photo??'')?p.photo:'';if(url)return `<img src="${esc(url)}" alt="${esc(p.name)}" data-player-image loading="lazy" referrerpolicy="no-referrer">`;return `<svg viewBox="0 0 120 142" role="img" aria-label="Illustrated avatar for ${esc(p.name)}"><rect width="120" height="142" fill="${bg}"/><circle cx="92" cy="24" r="49" fill="#ffffff35"/><path d="M15 145v-28c0-20 17-35 45-35s45 15 45 35v28Z" fill="${shirt}"/><path d="m39 88 21 18 21-18-7-5H46Z" fill="#fff9"/><path d="M51 72h18v23l-9 7-9-7Z" fill="${skin}"/><ellipse cx="60" cy="55" rx="23" ry="29" fill="${skin}"/><path d="M38 51V37c0-16 43-19 44 0v15l-5-7-3-11c-9 8-20 6-29 5l-3 11Z" fill="#303b30"/><path d="M38 57c-7-2-5 13 1 12m42-12c7-2 5 13-1 12" fill="${skin}"/><path d="M47 54h7m12 0h7" stroke="#503b2c" stroke-width="2" stroke-linecap="round"/><circle cx="51" cy="59" r="1.2" fill="#342d27"/><circle cx="69" cy="59" r="1.2" fill="#342d27"/><path d="m60 60-2 8h4m-10 9q8 5 16 0" stroke="#9a664b" stroke-width="1.5" fill="none" stroke-linecap="round"/><path d="M42 132v-25m36 25v-25" stroke="#ffffff35" stroke-width="2"/><path d="m53 114 7-5 7 5v8l-7 4-7-4Z" fill="#ffffffaa"/><path d="m57 119 3-5 3 5" fill="${shirt}"/>${large?'<path d="M8 126h104" stroke="#ffffff20"/>':''}</svg>`;}
function teamLogo(t){if(t.logo&&/^data:image\/(png|jpeg|webp);base64,/i.test(t.logo))return `<img src="${esc(t.logo)}" alt="${esc(t.name)} logo">`;const shapes={crown:'<path d="m23 36 7 18h40l7-18-16 10-11-22-11 22Z" fill="#ffffff"/><path d="M31 60h38v6H31Z" fill="#ffffff99"/>',wave:'<path d="M20 53c9-19 23-22 37-15l-8 9 17-4 13 12c-22-7-35 3-41 13l3-15Z" fill="white"/><path d="M28 72q22-12 45-2" stroke="#ffffff99" stroke-width="4" fill="none"/>',bolt:'<path d="m53 23-24 33h20l-4 25 28-37H53l6-21Z" fill="white"/>',wing:'<path d="m25 31 42 15 12-4-15 27-24 5 15-19-25-7 19 1Z" fill="white"/><path d="m33 24 31 15-21-4Z" fill="#ffffff77"/>'};return `<svg viewBox="0 0 100 108" role="img" aria-label="${esc(t.name)} logo"><path d="M50 5 91 19v43c0 22-41 42-41 42S9 84 9 62V19Z" fill="${esc(t.color)}"/><path d="M50 11 84 23v39c0 16-34 34-34 34S16 78 16 62V23Z" fill="none" stroke="#ffffff38" stroke-width="1.5"/>${shapes[t.symbol]??shapes.crown}</svg>`;}
function trophyIllustration(){return `<svg class="empty-illustration" viewBox="0 0 110 110" aria-hidden="true"><circle cx="55" cy="55" r="49" fill="#eef3e4"/><circle cx="55" cy="55" r="38" fill="none" stroke="#d8e3c8" stroke-dasharray="3 5"/><path d="M39 25h32v22c0 12-8 18-16 18s-16-6-16-18Z" fill="#9bb879"/><path d="M39 30H25v12c0 13 14 16 14 16m32-28h14v12c0 13-14 16-14 16" fill="none" stroke="#9bb879" stroke-width="5"/><path d="M55 66v15m-15 3h30" stroke="#68844d" stroke-width="5" stroke-linecap="round"/><path d="m55 35 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z" fill="#e9f2dc"/></svg>`;}
function toast(message){const box=document.querySelector('#toast');box.textContent=message;box.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('visible'),3400);}
function commit(fn){const next=structuredClone(state);fn(next);try{localStorage.setItem(storageKey,JSON.stringify(next));}catch{throw Error('Could not save in this browser. Enable browser storage and try again.');}state=next;}
function statusTag(status){return `<span class="tag ${status==='Sold'?'green':status==='Unsold'?'amber':status==='Current'?'dark':''}"><i class="badge-dot"></i>${esc(status==='Current'?'On the block':status)}</span>`;}
function canNavigate(stage){if(stage==='overview')return true;if(stage==='import')return !state.history.length&&!state.currentId&&!ui.spinning;if(stage==='teams'||stage==='settings')return state.imported;if(['results','players','unsold'].includes(stage))return state.imported;if(stage==='live')return state.imported&&state.teams.length>0;return false;}
function toggleSidebar(){
  ui.sidebarCollapsed=!ui.sidebarCollapsed;
  try{localStorage.setItem(sidebarPreferenceKey,String(ui.sidebarCollapsed));}catch{}
  document.querySelector('.app-shell')?.classList.toggle('sidebar-collapsed',ui.sidebarCollapsed);
  const button=document.querySelector('[data-action="toggle-sidebar"]');
  if(button){const label=ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar';button.setAttribute('aria-expanded',String(!ui.sidebarCollapsed));button.setAttribute('aria-label',label);button.title=label;button.innerHTML=icon(ui.sidebarCollapsed?'expand':'collapse');}
}
function navigate(stage){if(!canNavigate(stage))return;if(stage!=='live')clearTimeout(autoTimer);ui.filter='All';ui.search='';commit(s=>s.stage=stage);render();window.scrollTo({top:0,behavior:'smooth'});}
function shell(content){const nav=[['live','wheel','Auction'],['teams','shield','Teams'],['players','users','Players'],['unsold','reset','Unsold'],['results','chart','Results']];return `<div class="app-shell ${state.stage==='live'?'auction-shell':''} ${ui.sidebarCollapsed?'sidebar-collapsed':''}"><header class="site-header"><button class="brand" data-action="nav" data-stage="live" aria-label="Auction House home">${state.eventLogo?`<img class="event-logo" src="${esc(state.eventLogo)}" alt="Event logo">`:crest('brand-crest')}<span><strong>${esc(state.eventName)}</strong><small>PLAYER AUCTION · ${esc(state.season)}</small></span></button><nav class="main-nav" aria-label="Auction navigation">${nav.map(([s,i,l])=>`<button class="nav-button ${state.stage===s?'active':''}" data-action="nav" data-stage="${s}" aria-label="${l}" title="${l}" ${canNavigate(s)?'':'disabled'} ${state.stage===s?'aria-current="page"':''}>${icon(i)}<span>${l}</span>${s==='unsold'&&stats(state).unsold?`<b>${stats(state).unsold}</b>`:''}</button>`).join('')}</nav><div class="header-actions"><button class="icon-btn" data-action="nav" data-stage="import" title="Import players" aria-label="Import players" ${canNavigate('import')?'':'disabled'}>${icon('upload')}</button><button class="organizer-button" data-action="nav" data-stage="settings" title="Auction settings"><span class="organizer-avatar">A<i></i></span><span>Organizer</span>${icon('spark')}</button></div></header><main class="main ${state.stage==='live'?'auction-main':'page-main'}">${content}</main><footer class="site-footer"><span>© 2026 Auction House. <span class="footer-muted">A fair chance. A stronger squad.</span></span><span>${state.sampleData?'Sample workspace':'Imported roster'} · Saved in your browser</span><button data-action="reset" title="Reset to sample auction">${icon('reset')}Reset demo</button></footer></div>`;}
function pageHead(step,title,subtitle,extra=''){return `<div class="page-head"><div><p class="eyebrow">AUCTION HOUSE / ${state.stage==='import'?'REGISTRATION IMPORT':state.stage.toUpperCase()}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="page-head-actions">${extra}</div></div>`;}
function importView(){const mapped=mapRows(state.rows,state.mapping),valid=mapped.filter(p=>!p.errors.length).length,headers=Object.keys(state.rows[0]??{});const mappedHeaders=Object.values(state.mapping).filter(Boolean),ignored=headers.filter(h=>!mappedHeaders.includes(h));return pageHead(1,'Import your players.','Your Google Form did the registration. We’ll take it from here.',`<button class="btn" data-action="sample-download">${icon('download')}Sample Excel</button>`)+`<div class="import-layout"><section class="card"><div class="card-head"><div><h2>Registration sheet</h2><p class="caption">Start with our sample sheet, or upload your own.</p></div><span class="tag green">${state.rows.length} players ready to review</span></div><div class="upload-zone" tabindex="0" role="button" aria-label="Upload a registration Excel or CSV file" data-action="upload"><div class="file-symbol">${icon('file')}<small>XLSX</small></div><div class="upload-copy"><h3>${ui.importing?'Reading your sheet…':state.sampleData?'Your sample sheet is ready.':'Your registration sheet is ready.'}</h3><p class="file-name">${esc(ui.fileName)}</p><p>Choose or drop an .xlsx or .csv file to replace it</p></div><button class="btn" data-action="upload">${icon('upload')}Browse files</button></div><input class="hidden" id="file-input" type="file" accept=".xlsx,.csv"><div class="preview-label"><h3>Player preview</h3><span>Showing ${Math.min(6,mapped.length)} of ${mapped.length} rows</span></div><div class="table-scroll"><table><thead><tr><th>Player</th><th>Role</th><th>Category</th><th>Age</th><th>Validation</th></tr></thead><tbody>${mapped.slice(0,6).map(p=>`<tr><td><div class="player-cell"><div class="avatar">${portrait(p)}</div><div><strong>${esc(p.name||'Missing name')}</strong><small>${esc(p.id)}</small></div></div></td><td>${esc(p.role)}</td><td><span class="tag">${esc(p.category||'—')}</span></td><td class="source-id">${esc(p.age||'—')}</td><td>${p.errors.length?`<span class="tag red" title="${esc(p.errors.join(', '))}">Needs attention</span>`:`<span class="validation">${icon('checkcircle')}Ready</span>`}</td></tr>`).join('')}</tbody></table></div><div class="import-foot"><span class="validation">${icon(valid===mapped.length?'checkcircle':'info')}${valid} valid players · ${mapped.length-valid} errors</span><span class="tag">${ignored.length} extra fields excluded</span></div></section><aside><section class="card mapping-card"><div class="card-head"><div><h2>Keep only what matters</h2><p class="caption">Map your sheet to the auction.</p></div>${icon('grid')}</div><div class="mapping-body">${[['id','Player ID',''],['name','Player name','Required'],['role','Playing role',''],['category','Category',''],['age','Age',''],['city','City',''],['photo','Photo URL','']].map(([key,label,required])=>`<div class="mapping-field"><label for="map-${key}">${label}${required?' <em>*</em>':''}</label><div class="field-name">${icon('arrow')}<select id="map-${key}" data-map="${key}" aria-label="Source column for ${label}"><option value="">${key==='id'?'Auto-generate':key==='name'?'Select a column':'Not imported'}</option>${headers.map(h=>`<option value="${esc(h)}" ${state.mapping[key]===h?'selected':''}>${esc(h)}</option>`).join('')}</select></div></div>`).join('')}<p class="caption">Player name is required. A unique ID is created when no ID column is selected.</p><div class="ignored-fields"><h3>${icon('eyeoff')}Not imported</h3><div class="ignored-chips">${ignored.length?ignored.map(h=>`<span>${esc(h)}</span>`).join(''):'<span>All source columns are mapped</span>'}</div></div></div></section><section class="note-card">${icon('shield')}<h3>Registration stays outside.</h3><p>No player sign-up is needed here. Only your mapped auction details are saved with the imported players.</p></section></aside></div><div class="step-footer"><p>${icon('info')}${state.sampleData?'All names and details shown are sample data.':'Review your mappings and player validation before continuing.'}</p><div class="right-buttons"><button class="btn primary" data-action="import-confirm" ${!mapped.length||valid!==mapped.length||!state.mapping.name||ui.importing?'disabled':''}>Use these ${mapped.length} players ${icon('arrow')}</button></div></div>`;}
function unitSwitch(){return `<div class="unit-switch" role="group" aria-label="Auction unit"><button class="${state.unit==='POINTS'?'selected':''}" data-action="unit" data-unit="POINTS" ${state.history.length?'disabled':''}>${icon('spark')}Points</button><button class="${state.unit==='INR'?'selected':''}" data-action="unit" data-unit="INR" ${state.history.length?'disabled':''}>₹ &nbsp; Rupees</button></div>`;}
function teamsView(){return pageHead(2,'Build your contenders.','Create a team identity, set its budget, and choose the squad size.',`<button class="btn primary" data-action="add-team">${icon('plus')}Add team</button>`)+`<div class="setup-banner"><span class="circle-icon">${icon(state.history.length?'lock':'spark')}</span><div><h3>${state.history.length?'Auction unit and starting budgets are locked.':'Points or rupees. Your auction, your rules.'}</h3><p>Sales deduct from the winning team’s budget. Squad capacity is checked before every sale.</p></div>${unitSwitch()}</div><div class="teams-grid">${state.teams.map(t=>{const b=teamStats(state,t.id),cap=t.maxPlayers||11;return `<section class="card team-card"><div class="team-cover" style="--team-color:${esc(t.color)}"><span class="team-watermark">${esc(t.short)}</span><span class="team-logo">${teamLogo(t)}</span><div class="team-actions"><button class="icon-btn" data-action="edit-team" data-id="${esc(t.id)}" aria-label="Edit ${esc(t.name)}">${icon('edit')}</button><button class="icon-btn" data-action="delete-team" data-id="${esc(t.id)}" aria-label="Delete ${esc(t.name)}" ${b.count?'disabled title="Team has allocated players"':''}>${icon('trash')}</button></div></div><div class="team-card-body"><p class="eyebrow">${esc(t.short)} / TEAM ${state.teams.indexOf(t)+1}</p><h3>${esc(t.name)}</h3><div class="team-budget-main"><span>AVAILABLE BUDGET</span><strong>${money(b.remaining,state.unit)}</strong></div><div class="budget-track"><i style="width:${b.budget?b.remaining/b.budget*100:0}%;background:${esc(t.color)}"></i></div><div class="team-card-numbers"><span>Starting<strong>${money(b.budget,state.unit)}</strong></span><span>Spent<strong>${money(b.spent,state.unit)}</strong></span><span>Squad<strong>${b.count} / ${cap}</strong></span></div><button class="btn full" data-action="squad" data-id="${esc(t.id)}">${icon('users')}View squad ${icon('arrow')}</button></div></section>`;}).join('')}</div><div class="step-footer"><p>${icon('shield')}Sold players keep their allocations through every unsold round.</p><button class="btn primary" data-action="nav" data-stage="live">Enter auction room ${icon('arrow')}</button></div>`;}
function teamBoard(){const c=stats(state);return `<aside class="team-board card" id="auction-sidebar" aria-label="Team budgets and player counts"><div class="team-board-head"><div><h2>TEAMS</h2><p>${state.teams.length} contenders · ${state.unit==='INR'?'Rupees':'Points'}</p></div><button class="sidebar-toggle icon-btn" data-action="toggle-sidebar" aria-controls="auction-sidebar" aria-expanded="${!ui.sidebarCollapsed}" aria-label="${ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar'}" title="${ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar'}">${icon(ui.sidebarCollapsed?'expand':'collapse')}</button></div><div class="team-board-list">${state.teams.map(t=>{const b=teamStats(state,t.id),cap=t.maxPlayers||11;return `<button class="board-team" data-action="squad" data-id="${esc(t.id)}" style="--team-color:${esc(t.color)}" title="${esc(t.name)} · ${money(b.remaining,state.unit)} remaining · ${b.count}/${cap} players" aria-label="${esc(t.name)}, ${money(b.remaining,state.unit)} remaining, ${b.count} of ${cap} players"><span class="board-team-head"><span class="tiny-logo">${teamLogo(t)}</span><strong>${esc(t.name)}</strong>${icon('arrow')}</span><span class="board-details"><span class="board-stat"><span>BUDGET LEFT</span><strong>${money(b.remaining,state.unit)}</strong></span><span class="budget-track"><i style="width:${b.budget?Math.max(0,b.remaining/b.budget*100):0}%"></i></span><span class="board-stat"><span>PLAYERS</span><strong>${b.count}<small> / ${cap}</small></strong></span><span class="squad-track"><i style="width:${Math.min(100,b.count/cap*100)}%"></i></span><span class="board-spent">${money(b.spent,state.unit)} spent <span>of ${money(b.budget,state.unit)}</span></span></span></button>`;}).join('')}</div><div class="team-board-foot"><span>${icon('shield')}Budgets protected</span><small>Squads and balances carry into unsold rounds.</small><button class="btn text small" data-action="nav" data-stage="teams">Manage teams ${icon('arrow')}</button></div></aside>`;}
function retryBanner(count){return `<section class="retry-banner"><span class="retry-icon">${icon('reset')}</span><div><h3>${count} unsold ${count===1?'player deserves':'players deserve'} another chance.</h3><p>Start an optional unsold round, or keep these results and export. Team balances carry forward.</p></div><button class="btn primary" data-action="retry-unsold">${icon('wheel')}Auction unsold players (${count})</button></section>`;}
function askUnsoldRound(){if(!isComplete(state))return;const count=stats(state).unsold;if(!count)return;openModal('Start the unsold auction round?',`<p>Only the ${count} unsold ${count===1?'player returns':'players return'} to the wheel. Sold players stay with their teams. Remaining budgets and squad counts carry forward.</p><div class="sale-summary"><div class="summary-row"><span>Next round</span><strong>Unsold round ${state.round+1}</strong></div><div class="summary-row"><span>Players in the pool</span><strong>${count}</strong></div></div>`,`<button class="btn" data-action="close-modal">Keep these results</button><button class="btn primary" data-action="confirm-retry-unsold">Start unsold round ${icon('arrow')}</button>`);ui.modal={type:'retry'};}
function beginUnsoldRound(){try{clearTimeout(autoTimer);commit(s=>startUnsoldRound(s));ui.last=null;ui.error='';ui.teamId=null;ui.amount='';ui.rotation=0;ui.filter='All';closeModal();render();window.scrollTo({top:0,behavior:'smooth'});toast('Unsold round '+state.round+' ready. Spin to begin.');}catch(e){toast(e.message);}}
function metrics(){const c=stats(state);return `<div class="metrics">${[['Total players',c.total,'users',''],['Sold players',c.sold,'checkcircle','sold'],['Unsold players',c.unsold,'clock','unsold'],['Still in the game',c.pending+c.current,'wheel','']].map(([l,n,i,cls])=>`<div class="metric ${cls}"><span class="metric-icon">${icon(i)}</span><div><p class="metric-label">${l}</p><strong class="metric-value">${String(n).padStart(2,'0')}</strong></div><span class="metric-trend">${cls==='sold'?'Allocated':cls==='unsold'?'Second chance':l==='Total players'?'Registered':'Available'}</span></div>`).join('')}</div>`;}
function wheelMarkup(){const pool=state.players.filter(p=>p.status==='Pending'||p.status==='Current'),n=pool.length||1,colors=['#bc9748','#ece0b9','#7b6638','#d5bb77','#443e2d','#aa8742'];const background=pool.length?`conic-gradient(${pool.map((_,i)=>`${colors[i%colors.length]} ${i*360/n}deg ${(i+1)*360/n}deg`).join(',')})`:'#292920';return `<div class="wheel-zone"><div class="wheel-orbit"></div><div class="wheel-outer"><svg class="wheel-pointer" viewBox="0 0 28 40" aria-hidden="true"><path d="M2 2h24v15L14 38 2 17Z" fill="#e2c57d" stroke="#fff3c6" stroke-width="1.5"/><circle cx="14" cy="12" r="3" fill="#362c16"/></svg><div class="wheel" id="spin-wheel" role="img" aria-label="Random player selection wheel" style="background:${background};transform:rotate(${ui.rotation}deg)"></div><button class="wheel-hub" data-action="spin" aria-label="Spin to select a random player" ${ui.spinning||state.currentId||!pool.length?'disabled':''}>${icon('spark')}<span>${ui.spinning?'PICKING':'SPIN'}</span></button></div></div>`;}
function currentPlayerCard(){const p=state.players.find(p=>p.id===state.currentId),display=state.display||{};return `<section class="current-card"><div class="spotlight-head"><span>${icon('users')}PLAYER SPOTLIGHT</span><span>${p&&!ui.spinning?esc(p.id):'NEXT IN THE ARENA'}</span></div>${!p||ui.spinning?`<div class="spotlight-empty">${crest('empty-crest')}<p class="eyebrow">${ui.spinning?'RANDOM SELECTION IN PROGRESS':'THE NEXT CHAPTER'}</p><h2>${ui.spinning?'Every player.<br>A fair chance.':isComplete(state)?'An auction<br>to remember.':'Your next star<br>is one spin away.'}</h2><p>${ui.spinning?'The next player will be revealed when the wheel stops.':isComplete(state)?'Export your results or give unsold players another chance.':'Complete a spin to begin the bidding process.'}</p></div>${isComplete(state)?'<div class="empty-sale"><button class="btn primary full" data-action="nav" data-stage="results">View results '+icon('arrow')+'</button></div>':''}`:`<div class="player-hero ${display.photo===false?'no-photo':''}">${display.photo!==false?`<div class="player-photo">${portrait(p,true)}</div>`:''}<div class="player-info"><span class="player-role">${esc(p.role)}</span><h2>${esc(p.name)}</h2><div class="player-meta"><span>${esc(p.category||'Open category')}</span>${display.age!==false&&p.age?`<span>${esc(p.age)} years</span>`:''}${display.city!==false&&p.city?`<span>${esc(p.city)}</span>`:''}</div><span class="player-selected">${icon('checkcircle')}Round ${state.round} · ${p.sourceRow?'Registration #'+p.sourceRow:'Registered player'}</span></div></div><div class="sale-form"><label class="field-label" for="sold-amount">Final sold amount <span>${state.unit==='INR'?'Indian rupees':'Auction points'}</span></label><div class="amount-input"><span class="amount-prefix">${state.unit==='INR'?'₹':icon('spark')}</span><input id="sold-amount" type="text" inputmode="${state.unit==='INR'?'decimal':'numeric'}" value="${esc(ui.amount)}" placeholder="Enter amount" autocomplete="off" aria-describedby="sale-error"><span class="amount-unit">${state.unit==='INR'?'INR':'PTS'}</span></div><div class="quick-amounts">${(state.unit==='INR'?[1000,2500,5000]:[100,250,500]).map(n=>`<button data-action="amount" data-value="${n}">+${n.toLocaleString('en-IN')}</button>`).join('')}</div><p class="field-label">Winning team <span>Select one</span></p><div class="team-picker" role="group" aria-label="Winning team">${state.teams.map(t=>{const b=teamStats(state,t.id),full=b.count>=(t.maxPlayers||11);return `<button class="team-choice ${ui.teamId===t.id?'selected':''}" data-action="select-team" data-id="${esc(t.id)}" aria-pressed="${ui.teamId===t.id}" ${full?'disabled':''}><span class="tiny-logo">${teamLogo(t)}</span><span class="choice-copy"><strong>${esc(t.name)}</strong><small>${full?'Squad full':money(b.remaining,state.unit)+' available'}</small></span>${ui.teamId===t.id?icon('check','team-check'):''}</button>`;}).join('')}</div><p class="error-text" id="sale-error" role="alert">${esc(ui.error)}</p><div class="outcome-actions"><button class="btn unsold-button" data-action="unsold">${icon('x')}UNSOLD</button><button class="btn primary" data-action="sold">${icon('check')}SOLD</button></div></div>`}</section>`;}
function liveView(){const c=stats(state),welcome=!state.history.length&&!state.currentId&&!ui.spinning;return `<div class="live-layout">${teamBoard()}<div class="auction-stage card"><div class="room-toolbar"><span class="live-indicator"><i></i>${state.round>1?'UNSOLD ROUND '+state.round:'LIVE AUCTION'}</span><span class="room-counts">${c.sold} sold <b>·</b> ${c.unsold} unsold <b>·</b> ${c.pending+c.current} available</span><button class="icon-btn" data-action="nav" data-stage="settings" aria-label="Auction settings" title="Auction settings">${icon('spark')}</button></div>${welcome?auctionWelcome():`<div class="auction-grid"><section class="wheel-card"><div class="wheel-card-head"><p class="eyebrow">${isComplete(state)?'ROUND COMPLETE':'A RANDOM PICK. A FAIR CHANCE.'}</p><h2>${ui.spinning?'The wheel is turning.':state.currentId?'Let the bidding begin.':'Let the wheel decide.'}</h2></div>${wheelMarkup()}<p class="wheel-center-label">${ui.spinning?'Choosing the next player…':state.currentId?'Confirm this player’s outcome to continue.':isComplete(state)?'The current round is complete.':'Spin for the next available player.'}</p><button class="btn primary large full" data-action="spin" ${ui.spinning||state.currentId||!c.pending?'disabled':''}>${ui.spinning?'<span class="loader"></span>SPINNING…':icon('wheel')+'SPIN FOR NEXT PLAYER'}</button><p class="wheel-note">${icon('eyeoff')}Player names stay off the wheel.</p><div class="wheel-footer"><div><strong>Automatic next spin</strong><p>After each confirmed result</p></div><label class="toggle-label"><input id="auto-next" type="checkbox" aria-label="Auto-spin next player" ${state.autoNext?'checked':''}></label></div></section>${currentPlayerCard()}</div>`}<div class="room-bottom"><span>${icon('shield')}${state.unit==='INR'?'Rupees':'Points'} auction · ${state.round>1?'Budgets carried forward':'No repeat selections'}</span><button data-action="nav" data-stage="players">Player list ${icon('arrow')}</button>${state.sampleData?`<button data-action="quick-demo" ${ui.spinning?'disabled':''}>Finish sample round ${icon('spark')}</button>`:''}</div>${ui.last?`<div class="last-result">${icon('checkcircle')}<span><strong>${esc(ui.last.name)}</strong> ${ui.last.status==='Sold'?'signed by '+esc(ui.last.teamName)+' for '+money(ui.last.amount,state.unit):'marked unsold'}.</span><small>${state.autoNext&&c.pending?'Next spin starts automatically':'Result saved'}</small></div>`:''}</div></div>`;}
function resultsView(){const c=stats(state),complete=isComplete(state),players=state.players.filter(p=>ui.filter==='All'||p.status===ui.filter);return pageHead(4,complete?'The final scorecard.':'Every outcome, in one place.',complete?'Your current round is complete. Keep these results or run an unsold round.':'Follow the latest results. The final export unlocks when this round finishes.',`<button class="btn ${complete?'primary':''}" data-action="export" ${complete?'':'disabled'}>${icon('download')}Export Excel</button>`)+`<section class="results-hero"><span class="trophy-icon">${icon(complete?'trophy':'chart')}</span><div><span class="eyebrow">ROUND ${state.round} / ${state.round>1?'UNSOLD AUCTION':'MAIN AUCTION'}</span><h2>${complete?(state.round>1?'Unsold round '+state.round+' complete.':'Main auction complete.'):'The auction is in play.'}</h2><p>${c.sold} players signed · ${c.unsold} unsold · ${money(c.totalAmount,state.unit)} total spent</p></div><span class="result-round-tag">${complete?'COMPLETED':(c.pending+c.current)+' REMAINING'}</span></section>${complete&&c.unsold?retryBanner(c.unsold):''}${metrics()}<div class="teams-grid results-teams">${state.teams.map(t=>{const b=teamStats(state,t.id);return `<section class="card team-result-card"><div class="team-result-title"><span class="tiny-logo">${teamLogo(t)}</span><div><h3>${esc(t.name)}</h3><small>${b.count} players in the squad</small></div></div><div class="team-totals"><div><span>Budget left</span><strong>${money(b.remaining,state.unit)}</strong></div><div><span>Spent</span><strong>${money(b.spent,state.unit)}</strong></div></div></section>`;}).join('')}</div><section class="card"><div class="card-head"><div class="results-tabs" role="group" aria-label="Filter player results">${['All','Sold','Unsold'].map(f=>`<button class="${ui.filter===f?'selected':''}" data-action="filter" data-filter="${f}" aria-pressed="${ui.filter===f}">${f==='All'?'All players':f}<span>${f==='All'?c.total:f==='Sold'?c.sold:c.unsold}</span></button>`).join('')}</div><span class="tag violet">${state.unit==='INR'?'INR':'POINTS'}</span></div><div class="table-scroll"><table><thead><tr><th>Player</th><th>Role</th><th>Status</th><th>Winning team</th><th>Final amount</th><th>Round</th><th></th></tr></thead><tbody>${players.map(p=>{const t=state.teams.find(t=>t.id===p.teamId);return `<tr><td><div class="player-cell"><span class="avatar">${portrait(p)}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.id)}</small></div></div></td><td>${esc(p.role)}</td><td>${statusTag(p.status)}</td><td>${t?`<span class="team-cell"><span class="tiny-logo">${teamLogo(t)}</span>${esc(t.name)}</span>`:'—'}</td><td><strong>${p.amount!==null?money(p.amount,state.unit):'—'}</strong></td><td>${p.round?'R'+p.round:'—'}</td><td>${p.status==='Sold'?`<button class="icon-btn" data-action="edit-result" data-id="${esc(p.id)}" aria-label="Edit result for ${esc(p.name)}" ${state.currentId||ui.spinning?'disabled':''}>${icon('edit')}</button>`:''}</td></tr>`;}).join('')||'<tr><td colspan="7" class="empty-table">No players with this status.</td></tr>'}</tbody></table></div><div class="results-bottom">${icon('file')}<div><strong>One workbook. The complete auction.</strong><p>Player Results · Team Allocations · Unsold Players · Summary · Auction History</p></div><span class="tag">.XLSX</span></div></section><section class="card activity-card"><div class="card-head"><div><h2>Round history</h2><p class="caption">Every attempt is kept, including earlier unsold outcomes.</p></div><span class="tag">${state.history.length} outcomes</span></div><div class="table-scroll"><table><thead><tr><th>Order</th><th>Player</th><th>Round</th><th>Outcome</th><th>Team</th><th>Amount</th></tr></thead><tbody>${state.history.slice().reverse().map(h=>`<tr><td>#${String(h.sequence).padStart(2,'0')}</td><td>${esc(state.players.find(p=>p.id===h.playerId)?.name??h.playerId)}</td><td>R${h.round}</td><td>${statusTag(h.status)}${h.action==='Correction'?'<span class="correction-label">Corrected</span>':''}</td><td>${esc(state.teams.find(t=>t.id===h.teamId)?.name??'—')}</td><td>${h.amount!==null?money(h.amount,state.unit):'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-table">Your confirmed outcomes will appear here.</td></tr>'}</tbody></table></div></section>`;}
function arenaArt(){return `<svg class="arena-art" viewBox="0 0 470 260" aria-hidden="true"><defs><linearGradient id="arena-light" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#a793ff"/><stop offset="1" stop-color="#7fc9dd"/></linearGradient></defs><g fill="none" stroke="#ffffff" opacity=".14"><ellipse cx="261" cy="157" rx="182" ry="91"/><ellipse cx="261" cy="157" rx="163" ry="80"/><ellipse cx="261" cy="157" rx="143" ry="67"/><path d="M85 130v40m19-65v70m29-90v86m40-97v91m50-99v91m52-92v89m51-82v78m45-70v62m36-52v42M82 149l58 4m-23-46 46 17m-1-43 26 34m38-49 8 43m50-43-4 43m56-33-21 39m58-18-39 30m66 5-47 6"/></g><ellipse cx="261" cy="170" rx="114" ry="48" fill="#a391ff" opacity=".06"/><path d="m242 141 29-2 13 51-31 3Z" fill="url(#arena-light)" opacity=".18"/><g fill="none" stroke="url(#arena-light)" stroke-width="2"><path d="m243 141 29-2 13 51-32 3Z"/><path d="m244 147 28-2m-20 40 30-3"/></g><g fill="#bfaeff"><circle cx="202" cy="171" r="4"/><circle cx="308" cy="163" r="4"/><circle cx="266" cy="135" r="4"/></g><g stroke="#ffffff" stroke-width="3" opacity=".25"><path d="m94 129-9-67m309 65 11-75"/><path d="m65 63 41-4m281-9 45 4"/></g><circle cx="271" cy="59" r="23" fill="#ffffff08"/><path d="m263 58 6 6 10-13" stroke="#c1afff" stroke-width="2" fill="none"/><text x="120" y="249" fill="#ffffff33" font-size="10" letter-spacing="5" font-family="sans-serif">EVERY PLAYER. A FAIR CHANCE.</text></svg>`;}
function overviewView(){const c=stats(state),purse=state.teams.reduce((n,t)=>n+teamStats(state,t.id).budget,0);return pageHead(0,'Your auction. Your arena.','Everything you need to run a great auction day.',`<button class="btn" data-action="nav" data-stage="import" ${canNavigate('import')?'':'disabled'}>${icon('upload')}Import players</button>`)+`<section class="overview-hero"><div class="hero-copy"><span class="hero-label"><i></i>${esc(state.eventName)} · ${esc(state.season)}</span><h2>Big moments.<br><span>Better auctions.</span></h2><p>Build your teams. Discover your next star.<br>Let a fair spin set the stage.</p><div class="hero-actions"><button class="btn white" data-action="nav" data-stage="live" ${canNavigate('live')?'':'disabled'}>${icon('play')}${isComplete(state)?'View auction room':'Open auction room'} ${icon('arrow')}</button><span>${c.pending+c.current} players ready for the spotlight</span></div></div>${arenaArt()}<span class="hero-corner">PLAYER AUCTION / 2026</span></section>${metrics()}<div class="overview-grid"><section class="card"><div class="card-head"><div><h2>Your teams</h2><p class="caption">${state.teams.length} teams · ${money(purse,state.unit)} total starting budget</p></div><button class="btn text small" data-action="nav" data-stage="teams">Manage ${icon('arrow')}</button></div><div class="overview-team-list">${state.teams.map(t=>{const b=teamStats(state,t.id);return `<button class="overview-team" data-action="squad" data-id="${esc(t.id)}"><span class="team-logo">${teamLogo(t)}</span><div><strong>${esc(t.name)}</strong><small>${b.count} players signed</small></div><span class="overview-balance"><strong>${money(b.remaining,state.unit)}</strong><small>remaining</small></span>${icon('arrow')}</button>`;}).join('')}</div></section><section class="card checklist-card"><div class="card-head"><div><h2>Ready for matchday?</h2><p class="caption">A simple route from sheet to squad.</p></div><span class="tag violet">${state.history.length?'IN PLAY':'GET SET'}</span></div>${[['file','Players imported',c.total+' player profiles ready','import'],['shield','Teams & budgets',state.teams.length+' teams with starting budgets','teams'],['wheel','Enter the auction room','Spin, assign a team, save the result','live'],['chart','Wrap up & export','Re-auction unsold players or export','results']].map(([i,t,d,v],n)=>`<button class="checklist-row" data-action="nav" data-stage="${v}" ${canNavigate(v)?'':'disabled'}><span class="check-step ${n<2?'done':''}">${n<2?icon('check'):String(n+1).padStart(2,'0')}</span><div><strong>${t}</strong><small>${esc(d)}</small></div>${icon('arrow')}</button>`).join('')}<div class="mode-line"><span>Auction unit</span>${unitSwitch()}</div></section></div><section class="card activity-card"><div class="card-head"><div><h2>Latest auction activity</h2><p class="caption">A record of every confirmed outcome.</p></div><span class="tag">ROUND ${state.round}</span></div>${state.history.length?`<div class="activity-list">${state.history.slice(-5).reverse().map(h=>{const p=state.players.find(p=>p.id===h.playerId),t=state.teams.find(t=>t.id===h.teamId);return `<div class="activity-row"><span class="activity-symbol ${h.status==='Sold'?'sold':'unsold'}">${icon(h.status==='Sold'?'check':'clock')}</span><div><strong>${esc(p?.name??h.playerId)}</strong><small>${h.status==='Sold'?'Signed by '+esc(t?.name??'Team'):'Remains unsold'} · Round ${h.round}</small></div>${statusTag(h.status)}<strong>${h.amount!==null?money(h.amount,state.unit):'—'}</strong></div>`;}).join('')}</div>`:`<div class="activity-empty">${icon('spark')}<div><strong>The first big moment is waiting.</strong><p>Confirm a sold or unsold result and it will appear here.</p></div><button class="btn text small" data-action="nav" data-stage="live">Go to auction ${icon('arrow')}</button></div>`}</section>`;}
function playerTile(p){const team=state.teams.find(t=>t.id===p.teamId);return `<article class="card player-tile"><div class="player-tile-top"><span class="source-id">${esc(p.id)}</span>${statusTag(p.status)}</div><div class="tile-portrait">${portrait(p,true)}</div><div class="player-tile-body"><span class="tile-role">${esc(p.role)}</span><h3>${esc(p.name)}</h3><p>${esc(p.category||'Open category')} ${p.age?'· '+esc(p.age)+' years':''}</p><div class="tile-bottom">${team?`<span class="team-cell"><span class="tiny-logo">${teamLogo(team)}</span>${esc(team.short)}</span><strong>${money(p.amount,state.unit)}</strong>`:`<span>${esc(p.city||'Registered player')}</span><span>${p.status==='Unsold'?'Awaiting another chance':p.status==='Current'?'In the spotlight':'Ready for auction'}</span>`}</div></div></article>`;}
function playersView(){const c=stats(state),players=state.players.filter(p=>(ui.filter==='All'||p.status===ui.filter)&&(!ui.search||[p.name,p.id,p.role,p.city].some(x=>String(x).toLowerCase().includes(ui.search.toLowerCase()))));return pageHead(0,'The players. The possibilities.','Import your registrations or manage player details in one place.',`<button class="btn" data-action="nav" data-stage="import" ${canNavigate('import')?'':'disabled'}>${icon('upload')}Import Excel</button><button class="btn primary" data-action="add-player" ${state.history.length||state.currentId?'disabled title="Add players before the first outcome"':''}>${icon('plus')}Add player</button>`)+`${metrics()}<div class="directory-toolbar"><div class="results-tabs" role="group" aria-label="Filter players">${['All','Pending','Sold','Unsold'].map(f=>`<button class="${ui.filter===f?'selected':''}" data-action="filter" data-filter="${f}" aria-pressed="${ui.filter===f}">${f==='All'?'All players':f==='Pending'?'Available':f}<span>${state.players.filter(p=>f==='All'||p.status===f).length}</span></button>`).join('')}</div><div class="search-field">${icon('users')}<input id="player-search" placeholder="Search name, ID or role…" aria-label="Search players" value="${esc(ui.search||'')}"></div></div><div class="players-grid">${players.length?players.map(p=>`<div class="player-item">${playerTile(p)}<div class="player-actions"><button data-action="edit-player" data-id="${esc(p.id)}">${icon('edit')}Edit profile</button><button data-action="delete-player" data-id="${esc(p.id)}" ${state.history.length||p.status!=='Pending'?'disabled':''} title="Delete player before auction starts" aria-label="Delete ${esc(p.name)}">${icon('trash')}</button></div></div>`).join(''):'<div class="empty-directory">No players match this filter.</div>'}</div>`;}
function unsoldView(){const c=stats(state),players=state.players.filter(p=>p.status==='Unsold');return pageHead(0,'Another chance. Same ambition.','The unsold pool keeps players ready for an optional next round.',`<span class="tag amber">${players.length} UNSOLD</span>`)+`<section class="unsold-hero"><span class="unsold-hero-icon">${icon('reset')}</span><div><h2>${players.length?'The story doesn’t end here.':'Every player gets a fair shot.'}</h2><p>${players.length?(isComplete(state)?'The current round is complete. Re-auction these players with the same team budgets.':'Finish the current round before starting an unsold auction.'):'Unsold players appear here after their outcomes are confirmed.'}</p></div>${players.length?`<button class="btn primary" data-action="retry-unsold" ${isComplete(state)?'':'disabled'}>${icon('wheel')}Auction unsold players (${players.length})</button>`:`<button class="btn" data-action="nav" data-stage="live">Back to auction ${icon('arrow')}</button>`}</section><div class="players-grid">${players.map(playerTile).join('')}</div>${players.length?'<p class="flow-hint">'+icon('shield')+'Sold players stay with their teams. Existing squads and remaining budgets are preserved.</p>':''}`;}
function settingsView(){const display=state.display||{photo:true,age:true,city:true};return pageHead(0,'Make it your auction.','Set your event identity, auction unit, and player display options.')+`<div class="settings-grid"><section class="card"><div class="card-head"><div><h2>Event branding</h2><p class="caption">Shown in the header and the Excel summary.</p></div>${icon('flag')}</div><div class="settings-body"><div class="event-logo-upload"><span>${state.eventLogo?`<img src="${esc(state.eventLogo)}" alt="Event logo">`:crest()}</span><div><button class="btn small" data-action="event-logo-upload">${icon('upload')}Upload event logo</button><p class="caption">PNG, JPG or WebP · Up to 1 MB</p><input id="event-logo-input" class="hidden" type="file" accept="image/png,image/jpeg,image/webp"></div></div><div class="form-field"><label for="event-name">Event name</label><input id="event-name" maxlength="80" value="${esc(state.eventName)}"></div><div class="form-field"><label for="season-name">Season / edition</label><input id="season-name" maxlength="60" value="${esc(state.season)}"></div><button class="btn primary" data-action="save-settings">${icon('check')}Save details</button></div></section><section class="card"><div class="card-head"><div><h2>Auction unit</h2><p class="caption">Choose points or Indian rupees.</p></div>${icon('spark')}</div><div class="settings-body"><div class="mode-line"><span>${state.history.length?'Locked after first result':'Choose your unit'}</span>${unitSwitch()}</div><p class="settings-note">Points use whole numbers. Rupees support two decimal places. Each team has its own starting budget.</p><button class="btn" data-action="nav" data-stage="teams">${icon('shield')}Manage budgets & squad limits ${icon('arrow')}</button></div><div class="card-head"><div><h2>Player card display</h2><p class="caption">Choose which details appear during bidding.</p></div>${icon('eyeoff')}</div><div class="settings-body display-options">${[['photo','Player photo'],['age','Player age'],['city','Player city']].map(([k,l])=>`<label><span>${l}</span><input type="checkbox" data-display="${k}" ${display[k]!==false?'checked':''}></label>`).join('')}</div></section></div><section class="card settings-info"><span class="circle-icon">${icon('upload')}</span><div><h3>Registration stays outside the system.</h3><p>Use Google Forms for registrations. Upload its Excel export and map only the fields you need.</p></div><button class="btn" data-action="nav" data-stage="import" ${canNavigate('import')?'':'disabled'}>Open import ${icon('arrow')}</button></section>`;}
function squadDialog(id){const t=state.teams.find(t=>t.id===id);if(!t)return;const b=teamStats(state,id),players=state.players.filter(p=>p.status==='Sold'&&p.teamId===id);openModal(esc(t.name)+' squad',`<div class="squad-summary"><span class="team-logo">${teamLogo(t)}</span><div><strong>${b.count} players</strong><p>${money(b.remaining,state.unit)} remaining · ${money(b.spent,state.unit)} spent</p></div></div><div class="squad-list">${players.map(p=>`<div class="squad-row"><span class="avatar">${portrait(p)}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></div><strong>${money(p.amount,state.unit)}</strong></div>`).join('')||'<p class="squad-empty">No players signed yet. Confirm a sale to build this squad.</p>'}</div>`,`<button class="btn primary" data-action="close-modal">Done ${icon('check')}</button>`);ui.modal={type:'squad'};}
function saveSettings(){const name=document.querySelector('#event-name')?.value.trim(),season=document.querySelector('#season-name')?.value.trim();if(!name){toast('Enter an event name.');return;}commit(s=>{s.eventName=name;s.season=season||s.season;});render();toast('Auction details saved.');}
function render(){app.innerHTML=shell(({overview:overviewView,import:importView,teams:teamsView,live:liveView,results:resultsView,players:playersView,unsold:unsoldView,settings:settingsView}[state.stage]??overviewView)());for(const img of app.querySelectorAll('[data-player-image]'))img.addEventListener('error',()=>{const parent=img.parentNode;parent.innerHTML='<span style="height:100%;display:grid;place-items:center;color:#759064;font-size:25px">'+icon('users')+'</span>';},{once:true});}
function spin(){if(ui.spinning||state.currentId)return;try{let pick;commit(s=>{pick=pickPlayer(s,()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296);s.stage='live';});ui.spinning=true;ui.teamId=null;ui.amount='';ui.error='';const token=++ui.spinToken;render();const wheel=document.querySelector('#spin-wheel'),start=ui.rotation,sectorCenter=(pick.index+.5)*360/pick.pool.length,target=start+360*5+((360-sectorCenter-(start%360)+360)%360);requestAnimationFrame(()=>requestAnimationFrame(()=>{if(wheel)wheel.style.transform=`rotate(${target}deg)`;}));ui.rotation=target;clearTimeout(spinTimer);spinTimer=setTimeout(()=>{if(token!==ui.spinToken)return;ui.spinning=false;render();},matchMedia('(prefers-reduced-motion: reduce)').matches?150:3550);}catch(e){toast(e.message);}}
function closeModal(){modalRoot.innerHTML='';ui.modal=null;if(lastFocus?.isConnected)lastFocus.focus();}
function openModal(title,body,foot){lastFocus=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div></section></div>`;setTimeout(()=>modalRoot.querySelector('input,button')?.focus(),10);}
function confirmOutcome(status){const p=state.players.find(p=>p.id===state.currentId);if(!p||ui.spinning)return;let amount=null,team=null;if(status==='Sold'){try{amount=validateSale(state,ui.amount,ui.teamId);team=state.teams.find(t=>t.id===ui.teamId);}catch(e){ui.error=e.message;render();document.querySelector('#sold-amount')?.focus();return;}}ui.modal={type:'outcome',status};openModal(status==='Sold'?'Confirm the sale':'Mark player unsold',`<p>${status==='Sold'?'Review the result before saving. The next spin starts after confirmation when auto-spin is on.':'This player leaves the current round without a team or amount. You can re-auction unsold players after the round finishes.'}</p><div class="sale-summary"><div class="summary-row"><span>Player</span><strong>${esc(p.name)}</strong></div><div class="summary-row"><span>Outcome</span><strong>${status}</strong></div>${team?`<div class="summary-row"><span>Winning team</span><strong>${esc(team.name)}</strong></div><div class="summary-row"><span>Sold amount</span><strong class="amount">${money(amount,state.unit)}</strong></div><div class="summary-row"><span>Team balance after sale</span><strong>${money(Math.round((teamStats(state,team.id).remaining-amount)*100)/100,state.unit)}</strong></div>`:''}</div>`,`<button class="btn" data-action="close-modal">Go back</button><button class="btn primary" data-action="confirm-outcome">${icon('check')}Save ${status==='Sold'?'sale':'unsold'}</button>`);ui.modal={type:'outcome',status};}
function saveOutcome(){const status=ui.modal?.status;if(!status)return;try{let p;commit(s=>{p=recordOutcome(s,status,ui.amount,ui.teamId);if(isComplete(s))s.stage='results';});ui.last={...p,teamName:state.teams.find(t=>t.id===p.teamId)?.name??''};ui.error='';ui.amount='';ui.teamId=null;closeModal();render();toast(status==='Sold'?'Sale saved.':'Unsold result saved.');clearTimeout(autoTimer);if(!isComplete(state)&&state.autoNext)autoTimer=setTimeout(()=>{if(state.autoNext&&!state.currentId)spin();},1800);if(isComplete(state))window.scrollTo({top:0,behavior:'smooth'});}catch(e){closeModal();ui.error=e.message;render();toast(e.message);}}
function teamDialog(id){const t=state.teams.find(t=>t.id===id)??{name:'',short:'',color:'#7258c9',symbol:'crown',logo:'',budgets:{POINTS:1000,INR:10000},maxPlayers:11};ui.logoDraft=t.logo;openModal(id?'Edit team branding':'Add a new team',`<div class="logo-upload"><span class="tiny-logo" id="logo-preview">${teamLogo({...t,name:t.name||'New team'})}</span><div><button class="btn small" data-action="logo-upload">${icon('upload')}Upload logo</button><p class="caption">PNG, JPG or WebP · Up to 1 MB</p><input id="logo-input" class="hidden" type="file" accept="image/png,image/jpeg,image/webp"></div></div><div class="form-field"><label for="team-name">Team name *</label><input id="team-name" value="${esc(t.name)}" placeholder="e.g. Royal Strikers" maxlength="50"></div><div class="form-two"><div class="form-field"><label for="team-short">Short name</label><input id="team-short" value="${esc(t.short)}" placeholder="e.g. RS" maxlength="5"></div><div class="form-field"><label for="team-color">Brand color</label><input id="team-color" class="color-input" type="color" value="${esc(t.color)}"></div></div><div class="form-field"><label for="team-budget">Starting budget (${state.unit==='INR'?'rupees':'points'}) *</label><input id="team-budget" type="text" inputmode="${state.unit==='INR'?'decimal':'numeric'}" value="${t.budgets?.[state.unit]??defaultBudget(state.unit)}" ${id&&state.history.length?'disabled':''}><p class="caption" style="margin-top:7px">${id&&state.history.length?'Starting budgets are locked after the first saved result.':'Sales deduct from this budget. Unsold results do not affect it.'}</p></div><div class="form-field"><label for="team-capacity">Maximum players</label><input id="team-capacity" type="number" min="1" max="1000" value="${t.maxPlayers||11}"><p class="caption">Sales are blocked when the squad is full.</p></div><p class="error-text" id="team-error" role="alert"></p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-team">${icon('check')}Save team</button>`);ui.modal={type:'team',id,symbol:t.symbol};}
function saveTeam(){const name=document.querySelector('#team-name').value.trim(),short=document.querySelector('#team-short').value.trim().toUpperCase()||name.split(' ').map(v=>v[0]).join('').slice(0,4),color=document.querySelector('#team-color').value,id=ui.modal.id;if(!name){document.querySelector('#team-error').textContent='Enter a team name.';return;}if(state.teams.some(t=>t.id!==id&&t.name.toLowerCase()===name.toLowerCase())){document.querySelector('#team-error').textContent='A team with that name already exists.';return;}try{commit(s=>{const old=s.teams.find(t=>t.id===id),budgets={POINTS:1000,INR:10000,...old?.budgets};if(!id||!s.history.length)budgets[s.unit]=validateBudget(document.querySelector('#team-budget').value,s.unit);const t={id:id??'t'+crypto.randomUUID(),name,short,color,symbol:ui.modal.symbol,logo:ui.logoDraft,budgets,maxPlayers:Number(document.querySelector('#team-capacity')?.value||11)};if(!Number.isInteger(t.maxPlayers)||t.maxPlayers<1||t.maxPlayers>1000)throw Error('Set a squad limit between 1 and 1,000.');if(id&&t.maxPlayers<teamStats(s,id).count)throw Error('The squad limit cannot be lower than its current player count.');if(id)s.teams=s.teams.map(team=>team.id===id?t:team);else s.teams.push(t);});closeModal();render();toast(id?'Team branding updated.':'Team added.');}catch(e){document.querySelector('#team-error').textContent=e.message;}}
function askReset(){openModal('Restart the sample auction?',`<p>This clears the auction results saved in this browser and loads the original six sample players and four teams.</p>`,`<button class="btn" data-action="close-modal">Keep my progress</button><button class="btn primary" data-action="confirm-reset">${icon('reset')}Restart demo</button>`);ui.modal={type:'reset'};}
function reset(){clearTimeout(autoTimer);clearTimeout(spinTimer);ui.spinToken++;ui.spinning=false;ui.rotation=0;ui.amount='';ui.teamId=null;ui.last=null;ui.error='';ui.filter='All';ui.search='';ui.fileName='arena_registrations.xlsx';try{const fresh=initialState();localStorage.setItem(storageKey,JSON.stringify(fresh));state=fresh;closeModal();render();window.scrollTo({top:0,behavior:'smooth'});toast('Fresh sample auction loaded.');}catch{toast('Could not reset browser storage.');}}
async function handleFile(file){if(!file)return;if(!/\.(xlsx|csv)$/i.test(file.name)){toast('Choose an .xlsx or .csv file.');return;}if(file.size>8*1024*1024){toast('Use a sheet smaller than 8 MB for this demo.');return;}ui.importing=true;render();try{const rows=await readWorkbook(file);if(!rows.length)throw Error('The sheet has no player rows.');if(rows.length>1000)throw Error('This design demo supports up to 1,000 players.');const headers=Object.keys(rows[0]),normalized=h=>h.toLowerCase().replace(/[^a-z0-9]/g,''),aliases={id:['registrationid','playerid','id','registrationnumber'],name:['fullname','playername','name'],role:['role','playingrole'],category:['category'],age:['age'],city:['city','location'],photo:['photo','photourl','imageurl']};const map=Object.fromEntries(Object.entries(aliases).map(([k,v])=>[k,headers.find(h=>v.includes(normalized(h)))??'']));commit(s=>{s.rows=rows;s.mapping=map;s.imported=false;s.players=[];s.sampleData=false;s.fileName=file.name;});ui.fileName=file.name;toast('Sheet loaded. Review the column mapping.');}catch(e){toast(e.message||'Could not read your sheet.');}finally{ui.importing=false;render();}}
function exportResults(){if(!isComplete(state))return;download(createWorkbook(workbookRows(state)),'Auction_House_Results.xlsx');openModal('Your workbook is ready.',`<p>The Excel file contains all ${state.players.length} players and their final outcomes in ${state.unit==='INR'?'rupees':'points'}. Your download has started.</p><div class="export-sheet-list">${workbookRows(state).map(s=>`<div class="summary-row"><strong>${esc(s.name)}</strong><span>${s.rows.length-1} rows</span></div>`).join('')}</div>`,`<button class="btn primary" data-action="close-modal">${icon('check')}Done</button>`);}
function quickDemo(){if(ui.spinning||!state.sampleData)return;openModal('Finish the sample auction?',`<p>We’ll fill the remaining players with illustrative results: sold players go to teams with sample amounts, and every third remaining player is unsold. Existing results stay as they are.</p>`,`<button class="btn" data-action="close-modal">Keep auctioning</button><button class="btn primary" data-action="confirm-quick-demo">Complete demo ${icon('arrow')}</button>`);ui.modal={type:'quick'};}
function completeDemo(){try{clearTimeout(autoTimer);commit(s=>{let i=0;while(s.players.some(p=>p.status==='Pending'||p.status==='Current')){if(!s.currentId)pickPlayer(s);const amount=s.unit==='INR'?[2500,4000,3000,5000][i%4]:[250,400,300,500][i%4],team=s.teams.find(t=>{const b=teamStats(s,t.id);return b.remaining>=amount&&b.count<(t.maxPlayers||11);});recordOutcome(s,i%3===2||!team?'Unsold':'Sold',amount,team?.id);i++;}s.stage='results';});closeModal();ui.last=null;render();window.scrollTo({top:0,behavior:'smooth'});toast('Sample auction completed. Final export is ready.');}catch(e){toast(e.message);}}
function crest(extra=''){const gradientId='crest-gold-'+(extra||'event');return `<svg class="crest ${extra}" viewBox="0 0 180 130" aria-hidden="true"><defs><linearGradient id="${gradientId}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f5e3a4"/><stop offset=".5" stop-color="#c9a34f"/><stop offset="1" stop-color="#846023"/></linearGradient></defs><g fill="url(#${gradientId})"><path d="M75 52C48 52 30 31 7 26c3 13 17 26 32 34L13 48c7 20 24 30 45 34L25 71c12 21 29 27 51 21L60 81l17 6Z"/><path d="M105 52c27 0 45-21 68-26-3 13-17 26-32 34l26-12c-7 20-24 30-45 34l33-11c-12 21-29 27-51 21l16-11-17 6Z"/><path d="m90 38 23 11v24c0 17-23 30-23 30S67 90 67 73V49Z"/></g><path d="m90 44 17 8v20c0 12-17 24-17 24S73 84 73 72V52Z" fill="#111414" stroke="#f1d384"/><path d="m79 61 5 6 6-15 6 15 5-6-2 19H81Z" fill="#dfbc65"/><path d="M85 85h10" stroke="#b99449" stroke-width="2"/><g fill="#d2ae59"><circle cx="90" cy="14" r="2"/><path d="m90 20 3 7-3 7-3-7Z"/><circle cx="59" cy="35" r="1.5"/><circle cx="121" cy="35" r="1.5"/></g></svg>`;}
function auctionWelcome(){const c=stats(state);return `<section class="auction-welcome">${crest('welcome-crest')}<p class="eyebrow">THE STAGE IS SET</p><h2>Auction Awaits</h2><p class="welcome-subtitle">Commence the bidding experience</p><button class="btn primary start-bidding" data-action="spin" ${!c.pending?'disabled':''}>${icon('spark')}START BIDDING${icon('spark')}</button><p class="welcome-availability"><i></i>${c.pending} players available · ${state.teams.length} teams ready</p><div class="welcome-shortcuts"><button data-action="nav" data-stage="import" ${canNavigate('import')?'':'disabled'}>${icon('upload')}Import players</button><span></span><button data-action="nav" data-stage="teams">${icon('shield')}Set up teams</button></div></section>`;}
function playerDialog(id){const p=state.players.find(p=>p.id===id)??{id:'',name:'',role:'Batter',category:'Senior',age:'',city:'',photo:''};if(!id&&(state.history.length||state.currentId))return;openModal(id?'Edit player profile':'Add a player',`<div class="form-field"><label for="player-name">Player name *</label><input id="player-name" maxlength="80" value="${esc(p.name)}"></div><div class="form-two"><div class="form-field"><label for="player-id">Player ID</label><input id="player-id" maxlength="50" value="${esc(p.id)}" placeholder="Auto-generate" ${id?'disabled':''}></div><div class="form-field"><label for="player-role">Playing role</label><input id="player-role" maxlength="50" value="${esc(p.role)}"></div></div><div class="form-two"><div class="form-field"><label for="player-category">Category</label><input id="player-category" maxlength="50" value="${esc(p.category)}"></div><div class="form-field"><label for="player-age">Age</label><input id="player-age" inputmode="numeric" value="${esc(p.age)}"></div></div><div class="form-field"><label for="player-city">City</label><input id="player-city" maxlength="60" value="${esc(p.city)}"></div><div class="form-field"><label for="player-photo">Photo URL</label><input id="player-photo" type="url" value="${esc(p.photo)}" placeholder="https://..."></div><p class="error-text" id="player-error" role="alert"></p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-player">${icon('check')}Save player</button>`);ui.modal={type:'player',id};}
function syncRows(s){s.rows=s.players.map(p=>Object.fromEntries(Object.entries(s.mapping).filter(([,h])=>h).map(([k,h])=>[h,p[k]??''])));s.fileName='Edited player roster';s.sampleData=false;}
function savePlayer(){const get=k=>document.querySelector('#player-'+k)?.value.trim()||'',id=ui.modal?.id,name=get('name');if(!name){document.querySelector('#player-error').textContent='Enter a player name.';return;}try{commit(s=>{const old=s.players.find(p=>p.id===id),nextId=id||get('id')||'PL-'+crypto.randomUUID().slice(0,8).toUpperCase();if(!id&&(s.history.length||s.currentId))throw Error('Add players before the auction begins.');if(s.players.some(p=>p.id===nextId&&p.id!==id))throw Error('This player ID already exists.');const photo=get('photo');if(photo&&!/^https?:\/\//i.test(photo))throw Error('Use an https:// or http:// photo URL.');const age=get('age');if(age&&(!/^\d+$/.test(age)||Number(age)>120))throw Error('Enter a valid whole-number age.');const p={...(old||{status:'Pending',teamId:null,amount:null,sequence:null,timestamp:null,round:null}),id:nextId,name,role:get('role')||'Player',category:get('category'),age,city:get('city'),photo,sourceRow:old?.sourceRow||s.players.length+2};if(id)s.players=s.players.map(x=>x.id===id?p:x);else s.players.push(p);syncRows(s);});ui.fileName=state.fileName;closeModal();render();toast(id?'Player profile updated.':'Player added.');}catch(e){document.querySelector('#player-error').textContent=e.message;}}
function askDeletePlayer(id){const p=state.players.find(p=>p.id===id);if(!p||state.history.length||p.status!=='Pending')return;openModal('Delete '+esc(p.name)+'?',`<p>This removes the player from the pending auction roster.</p>`,`<button class="btn" data-action="close-modal">Keep player</button><button class="btn danger" data-action="confirm-delete-player" data-id="${esc(id)}">Delete player</button>`);ui.modal={type:'delete-player',id};}
function deletePlayer(id){if(state.history.length||state.players.find(p=>p.id===id)?.status!=='Pending')return;commit(s=>{s.players=s.players.filter(p=>p.id!==id);syncRows(s);});ui.fileName=state.fileName;closeModal();render();toast('Player deleted.');}
function editResult(id){const p=state.players.find(p=>p.id===id);if(!p||p.status!=='Sold'||ui.spinning||state.currentId)return;openModal('Edit sale result',`<p>Change the final amount or winning team. The previous team is refunded and the new allocation is checked against its budget and squad limit.</p><div class="sale-summary"><div class="summary-row"><span>Player</span><strong>${esc(p.name)}</strong></div></div><div class="form-field"><label for="result-amount">Final amount (${state.unit==='INR'?'rupees':'points'})</label><input id="result-amount" inputmode="${state.unit==='INR'?'decimal':'numeric'}" value="${esc(p.amount)}"></div><div class="form-field"><label for="result-team">Winning team</label><select id="result-team">${state.teams.map(t=>`<option value="${esc(t.id)}" ${t.id===p.teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><p class="error-text" id="result-error" role="alert"></p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-result">${icon('check')}Save correction</button>`);ui.modal={type:'result',id};}
function saveResult(){try{const id=ui.modal?.id,amount=document.querySelector('#result-amount').value,teamId=document.querySelector('#result-team').value;commit(s=>reviseSale(s,id,amount,teamId));closeModal();ui.last=null;render();toast('Sale corrected. Budgets and squads updated.');}catch(e){document.querySelector('#result-error').textContent=e.message;}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;try{
  if(action==='toggle-sidebar')toggleSidebar();
  else if(action==='nav')navigate(button.dataset.stage);
  else if(action==='upload')document.querySelector('#file-input')?.click();
  else if(action==='sample-download'){const headers=Object.keys(sampleRows[0]);download(createWorkbook([{name:'Registrations',rows:[headers,...sampleRows.map(r=>headers.map(h=>r[h]))]}]),'Auction_House_Registrations.xlsx');toast('Sample registration Excel downloaded.');}
  else if(action==='import-confirm'){const players=mapRows(state.rows,state.mapping);if(!players.length||players.some(p=>p.errors.length))throw Error('Fix player validation errors before importing.');commit(s=>{s.players=players.map(({errors,...p})=>p);s.rows=s.rows.map(row=>Object.fromEntries(Object.values(s.mapping).filter(Boolean).map(h=>[h,row[h]])));s.currentId=null;s.history=[];s.round=1;s.imported=true;s.stage='teams';});ui.last=null;render();window.scrollTo({top:0,behavior:'smooth'});toast(players.length+' players imported. Extra columns were excluded.');}
  else if(action==='add-player')playerDialog();
  else if(action==='edit-player')playerDialog(button.dataset.id);
  else if(action==='save-player')savePlayer();
  else if(action==='delete-player')askDeletePlayer(button.dataset.id);
  else if(action==='confirm-delete-player')deletePlayer(button.dataset.id);
  else if(action==='edit-result')editResult(button.dataset.id);
  else if(action==='save-result')saveResult();
  else if(action==='event-logo-upload')document.querySelector('#event-logo-input')?.click();
  else if(action==='squad')squadDialog(button.dataset.id);
  else if(action==='save-settings')saveSettings();
  else if(action==='unit'){commit(s=>changeUnit(s,button.dataset.unit));render();}
  else if(action==='start'){const name=document.querySelector('#event-name')?.value.trim()||state.eventName,season=document.querySelector('#season-name')?.value.trim()||state.season;commit(s=>{s.eventName=name;s.season=season;s.stage='live';});render();window.scrollTo({top:0,behavior:'smooth'});}
  else if(action==='spin')spin();
  else if(action==='select-team'){ui.teamId=button.dataset.id;ui.error='';render();}
  else if(action==='amount'){ui.amount=String((Number(ui.amount)||0)+Number(button.dataset.value));const input=document.querySelector('#sold-amount');if(input)input.value=ui.amount;}
  else if(action==='sold')confirmOutcome('Sold');
  else if(action==='unsold')confirmOutcome('Unsold');
  else if(action==='confirm-outcome')saveOutcome();
  else if(action==='close-modal')closeModal();
  else if(action==='add-team')teamDialog();
  else if(action==='edit-team')teamDialog(button.dataset.id);
  else if(action==='save-team')saveTeam();
  else if(action==='logo-upload')document.querySelector('#logo-input')?.click();
  else if(action==='delete-team'){const t=state.teams.find(t=>t.id===button.dataset.id);openModal('Delete '+esc(t.name)+'?',`<p>This removes the team from the auction’s team list. You can add it again before recording a sale.</p>`,`<button class="btn" data-action="close-modal">Keep team</button><button class="btn danger" data-action="confirm-delete-team" data-id="${esc(t.id)}">${icon('trash')}Delete team</button>`);ui.modal={type:'delete-team',id:t.id};}
  else if(action==='confirm-delete-team'){commit(s=>deleteTeam(s,button.dataset.id));closeModal();if(ui.teamId===button.dataset.id)ui.teamId=null;render();toast('Team deleted.');}
  else if(action==='reset')askReset();
  else if(action==='confirm-reset')reset();
  else if(action==='filter'){ui.filter=button.dataset.filter;render();}
  else if(action==='export')exportResults();
  else if(action==='retry-unsold')askUnsoldRound();
  else if(action==='confirm-retry-unsold')beginUnsoldRound();
  else if(action==='quick-demo')quickDemo();
  else if(action==='confirm-quick-demo')completeDemo();
}catch(e){toast(e.message);}});
document.addEventListener('input',event=>{if(event.target.id==='player-search'){const input=event.target,position=input.selectionStart;ui.search=input.value;render();const next=document.querySelector('#player-search');next?.focus();next?.setSelectionRange(position,position);}else if(event.target.id==='sold-amount'){ui.amount=event.target.value;ui.error='';const e=document.querySelector('#sale-error');if(e)e.textContent='';}});
document.addEventListener('change',async event=>{const e=event.target;try{if(e.dataset.display){commit(s=>{s.display??={photo:true,age:true,city:true};s.display[e.dataset.display]=e.checked;});toast('Player display updated.');}else if(e.id==='event-logo-input'){const f=e.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1024*1024)throw Error('Choose a PNG, JPG or WebP smaller than 1 MB.');const logo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the logo.'));reader.readAsDataURL(f);});commit(s=>s.eventLogo=logo);render();toast('Event logo updated.');}else if(e.dataset.map){commit(s=>s.mapping[e.dataset.map]=e.value);render();}else if(e.id==='auto-next'){commit(s=>s.autoNext=e.checked);if(!state.autoNext){clearTimeout(autoTimer);toast('Auto-spin paused. Your current player stays selected.');}}else if(e.id==='file-input')await handleFile(e.files[0]);else if(e.id==='event-name'||e.id==='season-name'){const value=e.value.trim();if(value)commit(s=>s[e.id==='event-name'?'eventName':'season']=value);}else if(e.id==='logo-input'){const f=e.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1024*1024)throw Error('Choose a PNG, JPG or WebP logo smaller than 1 MB.');ui.logoDraft=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read the logo.'));r.readAsDataURL(f);});document.querySelector('#logo-preview').innerHTML=`<img src="${esc(ui.logoDraft)}" alt="Uploaded logo preview">`;}}catch(err){toast(err.message);}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('.upload-zone');if(zone){e.preventDefault();zone.classList.add('dragover');}});document.addEventListener('dragleave',e=>e.target.closest('.upload-zone')?.classList.remove('dragover'));document.addEventListener('drop',e=>{const zone=e.target.closest('.upload-zone');if(zone){e.preventDefault();zone.classList.remove('dragover');handleFile(e.dataTransfer.files[0]);}});
document.addEventListener('keydown',e=>{if(modalRoot.firstChild){if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focus=Array.from(modalRoot.querySelectorAll('button,input,select')).filter(x=>!x.disabled&&!x.classList.contains('hidden'));const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}else if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('upload-zone')){e.preventDefault();document.querySelector('#file-input')?.click();}});
modalRoot.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
render();
